/**
 * The three reserved grader keys carry a rule the rest of the body does not: a
 * failed call must say why, and a call that says why must be marked failed.
 * Otherwise a consumer filtering on `ok` and one filtering on `error` disagree
 * about the same event.
 */
const toolResultCheck: FieldCheck = (value, path, errors) => {
  objectOf({
    allowUnknown: true,
    properties: {
      ok: boolean,
      latencyMs: number(0),
      queueMs: number(0),
      providerMs: number(0),
      roundMs: number(0),
      inputTokens: integer(0),
      outputTokens: integer(0),
      cachedInputTokens: integer(0),
      finishReason: string({ minLength: 1 }),
      error: nullable(objectOf({
        required: ["code", "message"],
        properties: {
          code: string({ minLength: 1 }),
          message: string({ minLength: 1 }),
          retryable: boolean,
        },
      })),
    },
  })(value, path, errors);
  if (!isRecord(value)) return;
  const failed = value.ok === false;
  const hasError = isRecord(value.error);
  if (failed && !hasError) errors.push(`${childPath(path, "error")}: is required when ok is false`);
  if (hasError && value.ok !== false) errors.push(`${childPath(path, "ok")}: must be false when an error is present`);
};

const traceEventCheck = objectOf({
