const REPLAY_INPUT_CHECKS: Readonly<Record<ArenaInputRecord["kind"], FieldCheck>> = {
  step: objectOf({
    required: ["kind", "tick", "stateHash", "action"],
    properties: { kind: literal("step"), tick: integer(0), stateHash, restaurantStateHash: stateHash, action: string({ minLength: 1 }) },
  }),
  time: objectOf({
