      roles: arrayOf(traceRole, { unique: true }),
    },
  }),
};

/** Dispatch on `kind` rather than trying every variant: the error names the field. */
const replayInputCheck: FieldCheck = (value, path, errors) => {
  if (!isRecord(value)) {
    errors.push(`${path}: must be an object`);
    return;
  }
  const check = REPLAY_INPUT_CHECKS[value.kind as ArenaInputRecord["kind"]];
  if (!check) {
    errors.push(`${childPath(path, "kind")}: must be one of ${Object.keys(REPLAY_INPUT_CHECKS).map((kind) => JSON.stringify(kind)).join(", ")}`);
    return;
  }
  check(value, path, errors);
};

const traceCheck = objectOf({
  required: [
    "version", "episodeId", "seed", "envVersion", "contractVersion",
    "runKind", "initialState", "events", "deletion", "replay", "terminal",
  ],
  properties: {
