function canonicalInitialState(state: Record<string, unknown>): Record<string, unknown> {
  const clone = JSON.parse(JSON.stringify(state)) as Record<string, unknown>;
  const workers = clone.workers;
  if (Array.isArray(workers)) {
    clone.workers = workers.map((worker) => {
      if (typeof worker !== "object" || worker === null) return worker;
      const entry = worker as Record<string, unknown>;
      return {
        ...entry,
        ...(typeof entry.role === "string" && LEGACY_ROLE_ALIASES[entry.role]
          ? { role: LEGACY_ROLE_ALIASES[entry.role] }
          : {}),
        ...(typeof entry.id === "string" && LEGACY_ROLE_ALIASES[entry.id]
          ? { id: LEGACY_ROLE_ALIASES[entry.id] }
          : {}),
      };
    });
  }
  return clone;
}

/**
 * Apply one recorded input to a live game and confirm the game lands where the
 * record says it did. `index` only names the input in the error message, so a
 * failure points at the input that diverged rather than at the trace as a whole.
 */
export function applyArenaReplayInput(
  game: RestaurantGame,
  input: ArenaInputRecord,
  index = 0,
): void {
  const tickBefore = game.state().episode.tick;
  if (input.tick !== tickBefore) {
    throw new Error(
      `replay input ${index} (${input.kind}) was recorded at tick ${input.tick} but replay is at tick ${tickBefore}`,
    );
  }
  switch (input.kind) {
    case "step":
      game.step(input.action);
      break;
    case "time":
      game.advanceTime();
      break;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      break;
    case "controllers":
      game.setExternalControllers(input.roles);
      break;
    default:
      throw new Error(`replay input ${index} has an unknown kind: ${JSON.stringify((input as { kind: unknown }).kind)}`);
  }
  const stateHash = computeStateHash(game.checkpointState());
  if (stateHash !== input.stateHash) {
    throw new Error(
      `replay checkpoint mismatch at input ${index} (${input.kind}, tick ${input.tick}): recorded ${input.stateHash}, replayed ${stateHash}`,
    );
  }
  if (input.restaurantStateHash) {
    const restaurantStateHash = computeStateHash(game.state());
    if (restaurantStateHash !== input.restaurantStateHash) {
      throw new Error(
        `replay state mismatch at input ${index} (${input.kind}, tick ${input.tick}): recorded ${input.restaurantStateHash}, replayed ${restaurantStateHash}`,
      );
    }
  }
}

/**
 * Rebuild the live game a trace records and return it, so a caller can go on
 * calling the engine's own methods on the result (`.state()`,
 * `.checkpointState()`, `.getTerminalStatus()`).
 *
 * Throws on the first disagreement between the record and what this engine
 * actually produces: the tick-0 state, any checkpoint hash, the final hashes,
 * or any part of the terminal record — status, tick, or reason.
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);

  // Before any input: the recorded opening world must be the world this seed
  // actually produces. A trace whose initialState was edited in any field —
  // including fields no schema rule covers, such as `cash` — is rejected here
  // even though every field still parses.
  const recordedInitialHash = computeStateHash(canonicalInitialState(trace.initialState));
  const engineInitialHash = computeStateHash(canonicalInitialState(game.getInitialState()));
  if (recordedInitialHash !== engineInitialHash) {
    throw new Error(
      `initial state mismatch for seed ${trace.seed} (${trace.replay.variation}): recorded ${recordedInitialHash}, engine ${engineInitialHash}`,
    );
  }

  trace.replay.inputs.forEach((input, index) => applyArenaReplayInput(game, input, index));

  const replayed = game.getReplayRecord();
  if (replayed.finalStateHash !== trace.replay.finalStateHash) {
    throw new Error(
      `final checkpoint mismatch: recorded ${trace.replay.finalStateHash}, replayed ${replayed.finalStateHash}`,
    );
  }
  if (
    trace.replay.finalRestaurantStateHash !== undefined
    && replayed.finalRestaurantStateHash !== trace.replay.finalRestaurantStateHash
  ) {
    throw new Error(
      `final state mismatch: recorded ${trace.replay.finalRestaurantStateHash}, replayed ${replayed.finalRestaurantStateHash}`,
    );
  }

  // The whole terminal record, not just the status: a trace whose `reason` was
  // altered is exactly as untrue as one whose `status` was.
  const terminal = game.getTerminalStatus();
  if (JSON.stringify(terminal) !== JSON.stringify(trace.terminal)) {
    throw new Error(
      `terminal mismatch: recorded ${JSON.stringify(trace.terminal)}, replayed ${JSON.stringify(terminal)}`,
    );
  }
  return game;
}

