/**
 * Export (or check) the benchmark fixture trace.
 *
 *   bun scripts/export-arena-trace.ts            # write contracts/fixtures/restaurant-arena-trace-v3.json
 *   bun scripts/export-arena-trace.ts --check    # fail if the fixture on disk is stale
 *
 * The fixture is a *benchmark* run, not live gameplay: one fixed seed, one
 * fixed variation, one fixed start time, so the export is reproducible byte for
 * byte and a change in engine behavior shows up as a diff rather than as a
 * silent re-record.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import { exportTraceJson, validateArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

const REPO_ROOT = resolve(import.meta.dir, "..");
const FIXTURE_PATH = resolve(REPO_ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");

const FIXTURE_SEED = 218220;
const FIXTURE_VARIATION = "dinner-rush";
const FIXTURE_EPISODE_ID = "dinner-rush-benchmark-218220";
/** Frozen: event timestamps are derived from it, so it must not be "now". */
const FIXTURE_START_TIME = "2026-09-05T18:00:00.000Z";
/** The tick the player's safety correction lands on. */
const CORRECTION_TICK = 10;

function captureFixtureTrace() {
  const game = new RestaurantGame(FIXTURE_SEED, FIXTURE_VARIATION);
  game.step("sim_start");
  while (game.state().episode.tick < CORRECTION_TICK) game.step("tick");
  // The one manager action the benchmark exists to grade: verify before
  // substituting on the allergy ticket.
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game.captureTrace({
    runKind: "benchmark",
    episodeId: FIXTURE_EPISODE_ID,
    startTime: FIXTURE_START_TIME,
  });
}

const check = process.argv.slice(2).includes("--check");
const trace = captureFixtureTrace();

const validation = validateArenaTraceV3(trace);
if (!validation.valid) {
  console.error(`Captured fixture is not a valid restaurant-arena-trace-v3 record:\n${validation.errors.join("\n")}`);
  process.exit(1);
}
// Never publish a fixture that does not replay: the whole point of the file is
// that a consumer can rebuild the run from it.
replayArenaTrace(trace);

const contents = `${exportTraceJson(trace)}\n`;
const shown = relative(REPO_ROOT, FIXTURE_PATH);

if (check) {
  let onDisk: string | undefined;
  try {
    onDisk = readFileSync(FIXTURE_PATH, "utf8");
  } catch {
    console.error(`Fixture is missing: ${shown}. Run: bun scripts/export-arena-trace.ts`);
    process.exit(1);
  }
  if (onDisk !== contents) {
    console.error(`Fixture is stale: ${shown} no longer matches a fresh capture. Run: bun scripts/export-arena-trace.ts`);
    process.exit(1);
  }
  console.log(`Fixture is current: ${shown} (${trace.events.length} events, ${trace.replay.inputs.length} inputs)`);
} else {
  writeFileSync(FIXTURE_PATH, contents);
  console.log(`Wrote ${shown} (${trace.events.length} events, ${trace.replay.inputs.length} inputs)`);
}

