/**
 * Natively replay a trace file and report whether the record is true.
 *
 *   bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>
 *
 * Accepts both export shapes: the indented JSON document from
 * `exportTraceJson` and the header-plus-events stream from `exportTraceJsonl`.
 * The trace has to pass schema validation *and* replay — every checkpoint hash,
 * the final hashes, and the whole terminal record — before this prints a pass.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { validateArenaTraceV3, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(2);
}

/** JSONL is one header line then one line per event; JSON is the whole record. */
function parseTrace(path: string, raw: string): RestaurantArenaTraceV3 {
  if (!path.endsWith(".jsonl")) return JSON.parse(raw) as RestaurantArenaTraceV3;
  const lines = raw.split("\n").filter((line) => line.trim().length > 0);
  const [header, ...events] = lines;
  if (!header) throw new Error("trace file is empty");
  return {
    ...(JSON.parse(header) as RestaurantArenaTraceV3),
    events: events.map((line) => JSON.parse(line)),
  };
}

const [target, ...rest] = process.argv.slice(2);
if (!target || rest.length > 0) usage();
const path = resolve(target);

try {
  const trace = parseTrace(path, readFileSync(path, "utf8"));
  const validation = validateArenaTraceV3(trace);
  if (!validation.valid) {
    console.error(`Schema validation failed for ${target}:\n${validation.errors.join("\n")}`);
    process.exit(1);
  }
  const game = replayArenaTrace(trace);
  const terminal = game.getTerminalStatus();
  console.log(
    `Native replay passed: ${trace.replay.inputs.length} inputs, tick ${terminal.tick}, ${terminal.status} (${terminal.reason ?? "no reason"})`,
  );
  console.log(`Final checkpoint ${trace.replay.finalStateHash}`);
} catch (error) {
  console.error(`Native replay failed for ${target}: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

