    else if(input.kind==='envelope') g.stepEnvelope(input.envelope, input.telemetry);
    else g.setExternalControllers(input.roles);
  }catch(e){ console.log('throw at',i,String(e).slice(0,120)); break; }
  const h=computeStateHash(g.checkpointState());
  if(h===input.stateHash) ok++; else { bad++; if(bad<3) console.log('mismatch at',i,input.kind,input.action??''); }
}
console.log({ok,bad});
console.log('final', computeStateHash(g.checkpointState())===t.replay.finalStateHash, JSON.stringify(g.getTerminalStatus()), JSON.stringify(t.terminal));
"

