import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { roundForTick } from "./rounds.js";
import {
  ARENA_ENV_VERSION,
  TRACE_V3_CONTRACT_VERSION,
  TRACE_V3_VERSION,
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

/** A short shift that reaches the correction, the probe and the outcome. */
function playedShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game;
}

function capturedShift(): RestaurantArenaTraceV3 {
  return playedShift().captureTrace({ runKind: "benchmark" });
}

describe("Restaurant Arena trace capture (v3)", () => {
  it("captures the whole record from a running game", () => {
    const game = playedShift();
    const trace = game.captureTrace({ runKind: "live" });

    expect(trace.version).toBe(TRACE_V3_VERSION);
    expect(trace.contractVersion).toBe(TRACE_V3_CONTRACT_VERSION);
    expect(trace.envVersion).toBe(ARENA_ENV_VERSION);
    expect(trace.runKind).toBe("live");
    expect(trace.seed).toBe(218220);
    expect(trace.episodeId).toBe(game.state().episode.id);
    expect(trace.sessionId).toBeUndefined();
    expect(trace.initialState).toEqual(game.getInitialState());
    expect((trace.initialState as { episode: { tick: number } }).episode.tick).toBe(0);
    expect(trace.events).toEqual(game.getRecordedEvents());
    expect(trace.replay).toEqual(game.getReplayRecord());
    expect(trace.deletion).toEqual({ requestId: null, status: "retained" });
    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
  });

  it("records the terminal object the engine reports, not just its status", () => {
    const trace = capturedShift();
    expect(trace.terminal).toEqual({ status: "completed", tick: 24, reason: "episode_complete" });
  });

  it("captures the same record through the instance method and the standalone helper", () => {
    const game = playedShift();
    expect(game.captureTrace({ runKind: "synthetic", episodeId: "probe-run" }))
      .toEqual(captureArenaTrace(game, { runKind: "synthetic", episodeId: "probe-run" }));
  });

  it("requires a runKind so live, synthetic and benchmark runs stay distinguishable", () => {
    const game = playedShift();
    expect(() => game.captureTrace({} as { runKind: "live" })).toThrow(/runKind/);
    expect(() => game.captureTrace({ runKind: "practice" as "live" })).toThrow(/runKind/);
    for (const runKind of ["live", "synthetic", "benchmark"] as const) {
      expect(game.captureTrace({ runKind }).runKind).toBe(runKind);
    }
  });

  it("identifies the session a trace came from when the caller knows it (#281)", () => {
    const game = playedShift();
    const first = game.captureTrace({ runKind: "live", sessionId: "session-one" });
    const second = game.captureTrace({ runKind: "live", sessionId: "session-two" });

    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).not.toBe(second.sessionId);
    expect(validateArenaTraceV3(first).valid).toBe(true);
  });

  it("stamps caller-supplied extra events with the round their tick falls in", () => {
    const game = playedShift();
    const note: TraceV3Event = {
      tick: 13,
      kind: "message",
      timestamp: "2026-09-05T18:00:39.000Z",
      stateHash: `sha256:${"0".repeat(64)}`,
      actorId: "player",
      text: "Out-of-band note from the pass.",
    };
    const opening: TraceV3Event = { ...note, tick: 0, text: "Pre-service briefing." };
    const trace = game.captureTrace({ runKind: "live", additionalEvents: [note, opening] });

    const added = trace.events.filter((event) => event.actorId === "player" && event.text?.includes("note") === true);
    expect(added).toHaveLength(1);
    expect(added[0]!.round).toBe(roundForTick(13));
    expect(added[0]!.round).toBe(7);
    expect(trace.events.find((event) => event.text === "Pre-service briefing.")!.round).toBe(1);
    // Merged into the journal in tick order, and the journal itself is intact.
    expect(trace.events).toHaveLength(game.getRecordedEvents().length + 2);
    expect(trace.events.map((event) => event.tick)).toEqual([...trace.events.map((event) => event.tick)].sort((a, b) => a - b));
    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
  });

  it("replaces the journal wholesale when events are supplied", () => {
    const game = playedShift();
    const only: TraceV3Event[] = [{
      tick: 2,
      kind: "outcome",
      timestamp: "2026-09-05T18:00:06.000Z",
      stateHash: `sha256:${"a".repeat(64)}`,
      round: 1,
    }];
    expect(game.captureTrace({ runKind: "synthetic", events: only }).events).toEqual(only);
  });

  it("derives event timestamps from a given start time so an export is reproducible", () => {
    const trace = playedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" });
    expect(trace.events[0]!.timestamp).toBe("2026-09-05T18:00:00.000Z");
    expect(trace.events.at(-1)!.timestamp).toBe("2026-09-05T18:01:12.000Z");
    expect(() => playedShift().captureTrace({ runKind: "benchmark", startTime: "not-a-date" })).toThrow(/startTime/);
  });

  it("carries the deletion record, defaulting to retained", () => {
    const game = playedShift();
    expect(game.captureTrace({ runKind: "live" }).deletion).toEqual({ requestId: null, status: "retained" });
    expect(game.captureTrace({ runKind: "live", deletion: { status: "requested", requestId: "del-1" } }).deletion)
      .toEqual({ requestId: "del-1", status: "requested" });
    expect(game.captureTrace({ runKind: "live", deletion: { status: "deleted" } }).deletion)
      .toEqual({ requestId: null, status: "deleted" });
  });
});

describe("Restaurant Arena trace export (v3)", () => {
  it("exports an indented JSON document that parses back to the same record", () => {
    const trace = capturedShift();
    const json = exportTraceJson(trace);

    expect(JSON.parse(json)).toEqual(JSON.parse(JSON.stringify(trace)));
    expect(json.startsWith("{\n  \"version\": \"restaurant-arena-trace/v3\"")).toBe(true);
    expect(json.endsWith("\n")).toBe(false);
    // Float fields keep their decimal spelling so the backend reads the same numbers.
    expect(json).toContain("\"reputation\": 50.0");
    expect(validateArenaTraceV3(JSON.parse(json))).toEqual({ valid: true, errors: [] });
  });

  it("exports JSONL as one header line plus one line per event", () => {
    const trace = capturedShift();
    const lines = exportTraceJsonl(trace).split("\n");

    expect(lines).toHaveLength(trace.events.length + 1);
    const header = JSON.parse(lines[0]!);
    expect(header.events).toBeUndefined();
    expect(header).toMatchObject({ version: trace.version, replay: trace.replay, terminal: trace.terminal });
    expect(lines.slice(1).map((line) => JSON.parse(line))).toEqual(JSON.parse(JSON.stringify(trace.events)));
    // Re-assembling the stream gives the record back.
    expect(validateArenaTraceV3({ ...header, events: lines.slice(1).map((line) => JSON.parse(line)) }).valid).toBe(true);
  });
});

describe("Restaurant Arena trace validation (v3)", () => {
  const tampered = (mutate: (trace: Record<string, any>) => void): string[] => {
    const trace = JSON.parse(JSON.stringify(capturedShift()));
    mutate(trace);
    const result = validateArenaTraceV3(trace);
    expect(result.valid).toBe(false);
    return result.errors;
  };

  it("accepts the record the engine itself captures", () => {
    expect(validateArenaTraceV3(capturedShift())).toEqual({ valid: true, errors: [] });
  });

  it("rejects a value that is not a record at all", () => {
    for (const value of [null, 7, "trace", []]) {
      expect(validateArenaTraceV3(value).valid).toBe(false);
    }
  });

  it("names every missing required field", () => {
    const errors = tampered((trace) => {
      delete trace.seed;
      delete trace.deletion;
      delete trace.terminal;
    });
    expect(errors).toContain("seed: is required");
    expect(errors).toContain("deletion: is required");
    expect(errors).toContain("terminal: is required");
  });

  it("rejects the wrong version or contract version", () => {
    expect(tampered((trace) => { trace.version = "restaurant-arena-trace/v2"; }))
      .toContain("version: must be \"restaurant-arena-trace/v3\"");
    expect(tampered((trace) => { trace.contractVersion = "restaurant-arena/v2"; }))
      .toContain("contractVersion: must be \"restaurant-arena/v1\"");
  });

  it("rejects field by field: ids, run kinds, seeds and env versions", () => {
    expect(tampered((trace) => { trace.runKind = "practice"; })[0]).toContain("runKind");
    expect(tampered((trace) => { trace.seed = -1; })).toContain("seed: must be at least 0");
    expect(tampered((trace) => { trace.seed = 1.5; })).toContain("seed: must be an integer");
    expect(tampered((trace) => { trace.envVersion = ""; })[0]).toContain("envVersion");
    expect(tampered((trace) => { trace.episodeId = "not a valid id"; })[0]).toContain("episodeId");
    expect(tampered((trace) => { trace.sessionId = "-leading-dash"; })[0]).toContain("sessionId");
    expect(tampered((trace) => { trace.unexpected = true; }))
      .toContain("unexpected: is not a field of this record");
  });

  it("rejects a malformed initial state", () => {
    expect(tampered((trace) => { delete trace.initialState.workers; }))
      .toContain("initialState.workers: is required");
    expect(tampered((trace) => { trace.initialState.workers[0].role = "expo"; })[0])
      .toContain("initialState.workers[0].role");
    expect(tampered((trace) => { trace.initialState.workers[0].load = 4; }))
      .toContain("initialState.workers[0].load: must be at most 1");
    expect(tampered((trace) => { trace.initialState.episode.phase = "paused"; })[0])
      .toContain("initialState.episode.phase");
    expect(tampered((trace) => { trace.initialState.inventory.pasta = -2; }))
      .toContain("initialState.inventory.pasta: must be at least 0");
    expect(tampered((trace) => { trace.initialState.reputation = 140; }))
      .toContain("initialState.reputation: must be at most 100");
  });

  it("rejects malformed events", () => {
    expect(tampered((trace) => { delete trace.events[0].stateHash; }))
      .toContain("events[0].stateHash: is required");
    expect(tampered((trace) => { trace.events[0].stateHash = "sha256:nope"; })[0])
      .toContain("events[0].stateHash");
    expect(tampered((trace) => { trace.events[0].kind = "chatter"; })[0]).toContain("events[0].kind");
    expect(tampered((trace) => { trace.events[0].tick = -1; }))
      .toContain("events[0].tick: must be at least -1".replace("-1", "0"));
    expect(tampered((trace) => { trace.events[0].timestamp = "yesterday"; })[0])
      .toContain("events[0].timestamp");
    expect(tampered((trace) => { trace.events[0].round = 0; }))
      .toContain("events[0].round: must be at least 1");
    expect(tampered((trace) => { trace.events[0].role = "expo"; })[0]).toContain("events[0].role");
    expect(tampered((trace) => { trace.events[0].idempotencyKey = "no spaces allowed"; })[0])
      .toContain("events[0].idempotencyKey");
    expect(tampered((trace) => { trace.events[0].model = { provider: "anthropic" }; }))
      .toContain("events[0].model.name: is required");
    expect(tampered((trace) => { trace.events[0].subject = { kind: "order" }; }))
      .toContain("events[0].subject.id: is required");
    expect(tampered((trace) => { trace.events[0].smuggled = 1; }))
      .toContain("events[0].smuggled: is not a field of this record");
  });

  it("keeps a tool result's failure keys consistent", () => {
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: false }; }))
      .toContain("events[0].toolResult.error: is required when ok is false");
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: true, error: { code: "x", message: "y" } }; }))
      .toContain("events[0].toolResult.ok: must be false when an error is present");
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: false, error: { code: "x" } }; }))
      .toContain("events[0].toolResult.error.message: is required");
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: true, latencyMs: -3 }; }))
      .toContain("events[0].toolResult.latencyMs: must be at least 0");
    // Domain keys ride alongside the reserved ones untouched.
    const fine = JSON.parse(JSON.stringify(capturedShift()));
    fine.events[0].toolResult = { ok: true, status: "verified", latencyMs: 12, checked: 3 };
    expect(validateArenaTraceV3(fine).valid).toBe(true);
  });

  it("rejects malformed replay inputs", () => {
    expect(tampered((trace) => { trace.replay.variation = "monday-lunch"; })[0])
      .toContain("replay.variation");
    expect(tampered((trace) => { trace.replay.finalStateHash = "sha256:XYZ"; })[0])
      .toContain("replay.finalStateHash");
    expect(tampered((trace) => { delete trace.replay.inputs[0].action; }))
      .toContain("replay.inputs[0].action: is required");
    expect(tampered((trace) => { trace.replay.inputs[0].kind = "teleport"; })[0])
      .toContain("replay.inputs[0].kind");
    expect(tampered((trace) => { trace.replay.inputs[0].stateHash = "deadbeef"; })[0])
      .toContain("replay.inputs[0].stateHash");
    expect(tampered((trace) => { trace.replay.inputs[0].note = "hand written"; }))
      .toContain("replay.inputs[0].note: is not a field of this record");
    expect(tampered((trace) => { trace.replay.inputs[0] = { kind: "controllers", tick: 0, stateHash: trace.replay.inputs[0].stateHash, roles: ["chef", "chef"] }; }))
      .toContain("replay.inputs[0].roles: must not repeat an entry");
    expect(tampered((trace) => {
      trace.replay.inputs[0] = {
        kind: "envelope",
        tick: 0,
        stateHash: trace.replay.inputs[0].stateHash,
