import { applyArenaReplayInput, replayArenaTrace } from "./replay.js";
import { computeStateHash, validateArenaTraceV3, type RestaurantArenaTraceV3 } from "./trace.js";

function playedShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game;
}

function captured(seed = 218220): RestaurantArenaTraceV3 {
  return playedShift(seed).captureTrace({ runKind: "live" });
}

const clone = (trace: RestaurantArenaTraceV3): RestaurantArenaTraceV3 =>
  JSON.parse(JSON.stringify(trace)) as RestaurantArenaTraceV3;

describe("Restaurant Arena native replay (v3)", () => {
  it("rebuilds and returns the live game itself", () => {
    const original = playedShift();
    const trace = original.captureTrace({ runKind: "live" });

    const game = replayArenaTrace(trace);

    expect(game).toBeInstanceOf(RestaurantGame);
    expect(game.state()).toEqual(original.state());
    expect(game.checkpointState()).toEqual(original.checkpointState());
    expect(game.getTerminalStatus()).toEqual(trace.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);
    // The rebuilt run re-records the same journal, so it can be captured again.
    expect(game.captureTrace({ runKind: "live" }).replay).toEqual(trace.replay);
  });

  it("replays a shift driven by player envelopes as well as keyboard steps", () => {
    const game = new RestaurantGame(218220, "dinner-rush");
    game.step("sim_start");
    game.step("tick");
    expect(game.submitPlayerIntervention({ kind: "priority", targetRole: "supply_lead", orderId: "order-2", priority: "high" }).accepted).toBe(true);
    game.step("tick");
    game.step("tick");
    expect(game.submitPlayerIntervention({ kind: "message", targetRole: "host", text: "Keep the queue informed." }).accepted).toBe(true);
    while (!game.isOver()) game.step("tick");

    const trace = game.captureTrace({ runKind: "live" });
    expect(trace.replay.inputs.some((input) => input.kind === "envelope")).toBe(true);
    expect(replayArenaTrace(trace).state()).toEqual(game.state());
  });

  it("replays a shift whose workers are driven from outside", () => {
    const game = new RestaurantGame(218220, "dinner-rush");
    game.setExternalControllers(["chef"]);
    game.step("sim_start");
    for (let i = 0; i < 4; i++) game.step("tick");
    const trace = game.captureTrace({ runKind: "synthetic" });

    expect(trace.replay.inputs[0]).toMatchObject({ kind: "controllers", roles: ["chef"] });
    expect(replayArenaTrace(trace).checkpointState()).toEqual(game.checkpointState());
  });

  it("replays the benchmark fixture on disk", () => {
    const path = join(import.meta.dir, "../../../contracts/fixtures/restaurant-arena-trace-v3.json");
    const fixture = JSON.parse(readFileSync(path, "utf8")) as RestaurantArenaTraceV3;

    expect(validateArenaTraceV3(fixture)).toEqual({ valid: true, errors: [] });
    expect(replayArenaTrace(fixture).getTerminalStatus()).toEqual(fixture.terminal);
  });

  it("starts from the engine's own tick-0 state, not the recorded snapshot", () => {
    const trace = clone(captured());
    // Schema-valid in every field, and wrong: this seed does not open on $5.
    (trace.initialState as { outcomes: { cash: number } }).outcomes.cash = 5;
    expect(validateArenaTraceV3(trace).valid).toBe(true);
    expect(() => replayArenaTrace(trace)).toThrow(/initial state mismatch/);
  });

  it("rejects any other edit to the recorded tick-0 state", () => {
    for (const mutate of [
      (state: any) => { state.inventory.pasta = 3; },
      (state: any) => { state.reputation = 60; },
      (state: any) => { state.tables[0].seats = 6; },
      (state: any) => { state.workers[0].location = "kitchen"; },
      (state: any) => { state.episode.maxTicks = 28; },
    ]) {
      const trace = clone(captured());
      mutate(trace.initialState);
      expect(() => replayArenaTrace(trace)).toThrow(/initial state mismatch/);
    }
  });

  it("still replays a historical trace that names the legacy expediter worker", () => {
    const trace = clone(captured());
    const workers = (trace.initialState as { workers: Array<{ id: string; role: string }> }).workers;
    const supplyLead = workers.find((worker) => worker.role === "supply_lead")!;
    supplyLead.role = "expediter";
    supplyLead.id = "worker-expediter";

    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
    const game = replayArenaTrace(trace);
    // Only the role name is legacy: the outcome it produces is unchanged.
    expect(game.getTerminalStatus()).toEqual(trace.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);
  });

  it("throws when a recorded checkpoint hash disagrees with replay", () => {
    const trace = clone(captured());
    trace.replay.inputs[5]!.stateHash = `sha256:${"1".repeat(64)}`;
    expect(() => replayArenaTrace(trace)).toThrow(/replay checkpoint mismatch at input 5/);
  });

  it("throws when a recorded restaurant-state hash disagrees with replay", () => {
    const trace = clone(captured());
    trace.replay.inputs[3]!.restaurantStateHash = `sha256:${"2".repeat(64)}`;
    expect(() => replayArenaTrace(trace)).toThrow(/replay state mismatch at input 3/);
  });

  it("throws when the recorded final hashes disagree with replay", () => {
    const dropped = clone(captured());
    dropped.replay.inputs.pop();
    expect(() => replayArenaTrace(dropped)).toThrow(/final checkpoint mismatch|terminal mismatch/);

    const tampered = clone(captured());
    tampered.replay.finalStateHash = `sha256:${"3".repeat(64)}`;
    expect(() => replayArenaTrace(tampered)).toThrow(/final checkpoint mismatch/);

    const tamperedState = clone(captured());
    tamperedState.replay.finalRestaurantStateHash = `sha256:${"4".repeat(64)}`;
    expect(() => replayArenaTrace(tamperedState)).toThrow(/final state mismatch/);
  });

  it("throws when a replay input is recorded at the wrong tick", () => {
    const trace = clone(captured());
    trace.replay.inputs[4]!.tick = 19;
    expect(() => replayArenaTrace(trace)).toThrow(/input 4 \(step\) was recorded at tick 19/);
  });

  it("throws when any part of the recorded terminal record disagrees", () => {
    for (const [field, value] of [["status", "abandoned"], ["tick", 23], ["reason", "player_quit"]] as const) {
      const trace = clone(captured());
      (trace.terminal as Record<string, unknown>)[field] = value;
      expect(validateArenaTraceV3(trace).valid).toBe(true);
      expect(() => replayArenaTrace(trace)).toThrow(/terminal mismatch/);
    }
  });

  it("applies a single recorded input and checks where it landed", () => {
    const trace = captured();
    const game = new RestaurantGame(trace.seed, trace.replay.variation);

    applyArenaReplayInput(game, trace.replay.inputs[0]!, 0);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.inputs[0]!.stateHash);
    // Out of order is a divergence, not something to paper over.
    expect(() => applyArenaReplayInput(game, trace.replay.inputs[9]!, 9)).toThrow(/tick/);
  });
});

