import { afterAll, describe, expect, it } from "bun:test";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { exportTraceJsonl, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";

const REPO_ROOT = resolve(import.meta.dir, "..");
const EXPORT_CLI = join(REPO_ROOT, "scripts/export-arena-trace.ts");
const REPLAY_CLI = join(REPO_ROOT, "scripts/replay-arena-trace.ts");
const FIXTURE = join(REPO_ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");

const fixtureBefore = readFileSync(FIXTURE, "utf8");
const workspace = mkdtempSync(join(tmpdir(), "arena-trace-cli-"));

function run(...args: string[]): { code: number; stdout: string; stderr: string } {
  const result = Bun.spawnSync({ cmd: ["bun", ...args], cwd: REPO_ROOT, stdout: "pipe", stderr: "pipe" });
  const decoder = new TextDecoder();
  return {
    code: result.exitCode ?? 1,
    stdout: decoder.decode(result.stdout),
    stderr: decoder.decode(result.stderr),
  };
}

/** Write a copy of the fixture with one field bent, and return its path. */
function tamperedTrace(name: string, mutate: (trace: RestaurantArenaTraceV3) => void): string {
  const trace = JSON.parse(fixtureBefore) as RestaurantArenaTraceV3;
  mutate(trace);
  const path = join(workspace, name);
  writeFileSync(path, JSON.stringify(trace, null, 2));
  return path;
}

afterAll(() => {
  // The writer test rewrites the real fixture; put back exactly what was there.
  writeFileSync(FIXTURE, fixtureBefore);
});

describe("scripts/export-arena-trace.ts", () => {
  it("reports the fixture is current when a fresh capture matches disk", () => {
    const result = run(EXPORT_CLI, "--check");
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Fixture is current");
  });

  it("writes the fixture and names the path it wrote", () => {
    const result = run(EXPORT_CLI);
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Wrote");
    expect(result.stdout).toContain("contracts/fixtures/restaurant-arena-trace-v3.json");
    expect(readFileSync(FIXTURE, "utf8")).toBe(fixtureBefore);
  });

  it("fails --check without rewriting the file when the fixture is stale", () => {
    writeFileSync(FIXTURE, fixtureBefore.replace("\"runKind\": \"benchmark\"", "\"runKind\": \"live\""));
    const result = run(EXPORT_CLI, "--check");
    expect(result.code).not.toBe(0);
    expect(result.stdout).not.toContain("Fixture is current");
    expect(readFileSync(FIXTURE, "utf8")).not.toBe(fixtureBefore);
    writeFileSync(FIXTURE, fixtureBefore);
  });
});

describe("scripts/replay-arena-trace.ts", () => {
  it("passes on the benchmark fixture", () => {
    const result = run(REPLAY_CLI, FIXTURE);
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Native replay passed");
  });

  it("passes on the JSONL form of the same trace", () => {
    const path = join(workspace, "fixture.jsonl");
    writeFileSync(path, exportTraceJsonl(JSON.parse(fixtureBefore) as RestaurantArenaTraceV3));
    const result = run(REPLAY_CLI, path);
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Native replay passed");
  });

  it("fails on a tampered, truncated or malformed trace", () => {
    const cases = [
      tamperedTrace("wrong-reason.json", (trace) => { trace.terminal.reason = "player_quit"; }),
      tamperedTrace("wrong-hash.json", (trace) => { trace.replay.inputs[4]!.stateHash = `sha256:${"1".repeat(64)}`; }),
      tamperedTrace("truncated.json", (trace) => { trace.replay.inputs.pop(); }),
      tamperedTrace("edited-cash.json", (trace) => { (trace.initialState as { outcomes: { cash: number } }).outcomes.cash = 5; }),
      tamperedTrace("no-seed.json", (trace) => { delete (trace as { seed?: number }).seed; }),
      join(workspace, "missing.json"),
    ];
    for (const path of cases) {
      const result = run(REPLAY_CLI, path);
      expect(result.code).not.toBe(0);
      expect(result.stdout).not.toContain("Native replay passed");
    }
  });

  it("explains itself when called with no trace path", () => {
    const result = run(REPLAY_CLI);
    expect(result.code).toBe(2);
    expect(result.stderr).toContain("Usage");
  });
});

