import { afterAll, describe, expect, it } from "bun:test";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { exportTraceJsonl, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";

const REPO_ROOT = resolve(import.meta.dir, "..");
const EXPORT_CLI = join(REPO_ROOT, "scripts/export-arena-trace.ts");
const REPLAY_CLI = join(REPO_ROOT, "scripts/replay-arena-trace.ts");
const FIXTURE = join(REPO_ROOT, "contracts/fixtures/restaurant-arena-trace-v3.json");

const fixtureBefore = readFileSync(FIXTURE, "utf8");
const workspace = mkdtempSync(join(tmpdir(), "arena-trace-cli-"));

function run(...args: string[]): { code: number; stdout: string; stderr: string } {
  const result = Bun.spawnSync({ cmd: ["bun", ...args], cwd: REPO_ROOT, stdout: "pipe", stderr: "pipe" });
  const decoder = new TextDecoder();
  return {
    code: result.exitCode ?? 1,
    stdout: decoder.decode(result.stdout),
    stderr: decoder.decode(result.stderr),
  };
}

/** Write a copy of the fixture with one field bent, and return its path. */
function tamperedTrace(name: string, mutate: (trace: RestaurantArenaTraceV3) => void): string {
  const trace = JSON.parse(fixtureBefore) as RestaurantArenaTraceV3;
  mutate(trace);
  const path = join(workspace, name);
  writeFileSync(path, JSON.stringify(trace, null, 2));
  return path;
}

afterAll(() => {
  // The writer test rewrites the real fixture; put back exactly what was there.
  writeFileSync(FIXTURE, fixtureBefore);
});

describe("scripts/export-arena-trace.ts", () => {
  it("reports the fixture is current when a fresh capture matches disk", () => {
    const result = run(EXPORT_CLI, "--check");
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Fixture is current");
  });

  it("writes the fixture and names the path it wrote", () => {
    const result = run(EXPORT_CLI);
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Wrote");
    expect(result.stdout).toContain("contracts/fixtures/restaurant-arena-trace-v3.json");
    expect(readFileSync(FIXTURE, "utf8")).toBe(fixtureBefore);
  });

  it("fails --check without rewriting the file when the fixture is stale", () => {
    writeFileSync(FIXTURE, fixtureBefore.replace("\"runKind\": \"benchmark\"", "\"runKind\": \"live\""));
    const result = run(EXPORT_CLI, "--check");
    expect(result.code).not.toBe(0);
    expect(result.stdout).not.toContain("Fixture is current");
    expect(readFileSync(FIXTURE, "utf8")).not.toBe(fixtureBefore);
    writeFileSync(FIXTURE, fixtureBefore);
  });
});

describe("scripts/replay-arena-trace.ts", () => {
  it("passes on the benchmark fixture", () => {
    const result = run(REPLAY_CLI, FIXTURE);
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Native replay passed");
  });

  it("passes on the JSONL form of the same trace", () => {
    const path = join(workspace, "fixture.jsonl");
    writeFileSync(path, exportTraceJsonl(JSON.parse(fixtureBefore) as RestaurantArenaTraceV3));
    const result = run(REPLAY_CLI, path);
    expect(result.code).toBe(0);
    expect(result.stdout).toContain("Native replay passed");
  });

  it("fails on a tampered, truncated or malformed trace", () => {
    const cases = [
      tamperedTrace("wrong-reason.json", (trace) => { trace.terminal.reason = "player_quit"; }),
      tamperedTrace("wrong-hash.json", (trace) => { trace.replay.inputs[4]!.stateHash = `sha256:${"1".repeat(64)}`; }),
      tamperedTrace("truncated.json", (trace) => { trace.replay.inputs.pop(); }),
      tamperedTrace("edited-cash.json", (trace) => { (trace.initialState as { outcomes: { cash: number } }).outcomes.cash = 5; }),
      tamperedTrace("no-seed.json", (trace) => { delete (trace as { seed?: number }).seed; }),
      join(workspace, "missing.json"),
    ];
    for (const path of cases) {
      const result = run(REPLAY_CLI, path);
      expect(result.code).not.toBe(0);
      expect(result.stdout).not.toContain("Native replay passed");
    }
  });

  it("explains itself when called with no trace path", () => {
    const result = run(REPLAY_CLI);
    expect(result.code).toBe(2);
    expect(result.stderr).toContain("Usage");
  });
});

import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { RestaurantGame } from "./restaurant-game.js";
import { applyArenaReplayInput, replayArenaTrace } from "./replay.js";
import { computeStateHash, validateArenaTraceV3, type RestaurantArenaTraceV3 } from "./trace.js";

function playedShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game;
}

function captured(seed = 218220): RestaurantArenaTraceV3 {
  return playedShift(seed).captureTrace({ runKind: "live" });
}

const clone = (trace: RestaurantArenaTraceV3): RestaurantArenaTraceV3 =>
  JSON.parse(JSON.stringify(trace)) as RestaurantArenaTraceV3;

describe("Restaurant Arena native replay (v3)", () => {
  it("rebuilds and returns the live game itself", () => {
    const original = playedShift();
    const trace = original.captureTrace({ runKind: "live" });

    const game = replayArenaTrace(trace);

    expect(game).toBeInstanceOf(RestaurantGame);
    expect(game.state()).toEqual(original.state());
    expect(game.checkpointState()).toEqual(original.checkpointState());
    expect(game.getTerminalStatus()).toEqual(trace.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);
    // The rebuilt run re-records the same journal, so it can be captured again.
    expect(game.captureTrace({ runKind: "live" }).replay).toEqual(trace.replay);
  });

  it("replays a shift driven by player envelopes as well as keyboard steps", () => {
    const game = new RestaurantGame(218220, "dinner-rush");
    game.step("sim_start");
    game.step("tick");
    expect(game.submitPlayerIntervention({ kind: "priority", targetRole: "supply_lead", orderId: "order-2", priority: "high" }).accepted).toBe(true);
    game.step("tick");
    game.step("tick");
    expect(game.submitPlayerIntervention({ kind: "message", targetRole: "host", text: "Keep the queue informed." }).accepted).toBe(true);
    while (!game.isOver()) game.step("tick");

    const trace = game.captureTrace({ runKind: "live" });
    expect(trace.replay.inputs.some((input) => input.kind === "envelope")).toBe(true);
    expect(replayArenaTrace(trace).state()).toEqual(game.state());
  });

  it("replays a shift whose workers are driven from outside", () => {
    const game = new RestaurantGame(218220, "dinner-rush");
    game.setExternalControllers(["chef"]);
    game.step("sim_start");
    for (let i = 0; i < 4; i++) game.step("tick");
    const trace = game.captureTrace({ runKind: "synthetic" });

    expect(trace.replay.inputs[0]).toMatchObject({ kind: "controllers", roles: ["chef"] });
    expect(replayArenaTrace(trace).checkpointState()).toEqual(game.checkpointState());
  });

  it("replays the benchmark fixture on disk", () => {
    const path = join(import.meta.dir, "../../../contracts/fixtures/restaurant-arena-trace-v3.json");
    const fixture = JSON.parse(readFileSync(path, "utf8")) as RestaurantArenaTraceV3;

    expect(validateArenaTraceV3(fixture)).toEqual({ valid: true, errors: [] });
    expect(replayArenaTrace(fixture).getTerminalStatus()).toEqual(fixture.terminal);
  });

  it("starts from the engine's own tick-0 state, not the recorded snapshot", () => {
    const trace = clone(captured());
    // Schema-valid in every field, and wrong: this seed does not open on $5.
    (trace.initialState as { outcomes: { cash: number } }).outcomes.cash = 5;
    expect(validateArenaTraceV3(trace).valid).toBe(true);
    expect(() => replayArenaTrace(trace)).toThrow(/initial state mismatch/);
  });

  it("rejects any other edit to the recorded tick-0 state", () => {
    for (const mutate of [
      (state: any) => { state.inventory.pasta = 3; },
      (state: any) => { state.reputation = 60; },
      (state: any) => { state.tables[0].seats = 6; },
      (state: any) => { state.workers[0].location = "kitchen"; },
      (state: any) => { state.episode.maxTicks = 28; },
    ]) {
      const trace = clone(captured());
      mutate(trace.initialState);
      expect(() => replayArenaTrace(trace)).toThrow(/initial state mismatch/);
    }
  });

  it("still replays a historical trace that names the legacy expediter worker", () => {
    const trace = clone(captured());
    const workers = (trace.initialState as { workers: Array<{ id: string; role: string }> }).workers;
    const supplyLead = workers.find((worker) => worker.role === "supply_lead")!;
    supplyLead.role = "expediter";
    supplyLead.id = "worker-expediter";

    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
    const game = replayArenaTrace(trace);
    // Only the role name is legacy: the outcome it produces is unchanged.
    expect(game.getTerminalStatus()).toEqual(trace.terminal);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.finalStateHash);
  });

  it("throws when a recorded checkpoint hash disagrees with replay", () => {
    const trace = clone(captured());
    trace.replay.inputs[5]!.stateHash = `sha256:${"1".repeat(64)}`;
    expect(() => replayArenaTrace(trace)).toThrow(/replay checkpoint mismatch at input 5/);
  });

  it("throws when a recorded restaurant-state hash disagrees with replay", () => {
    const trace = clone(captured());
    trace.replay.inputs[3]!.restaurantStateHash = `sha256:${"2".repeat(64)}`;
    expect(() => replayArenaTrace(trace)).toThrow(/replay state mismatch at input 3/);
  });

  it("throws when the recorded final hashes disagree with replay", () => {
    const dropped = clone(captured());
    dropped.replay.inputs.pop();
    expect(() => replayArenaTrace(dropped)).toThrow(/final checkpoint mismatch|terminal mismatch/);

    const tampered = clone(captured());
    tampered.replay.finalStateHash = `sha256:${"3".repeat(64)}`;
    expect(() => replayArenaTrace(tampered)).toThrow(/final checkpoint mismatch/);

    const tamperedState = clone(captured());
    tamperedState.replay.finalRestaurantStateHash = `sha256:${"4".repeat(64)}`;
    expect(() => replayArenaTrace(tamperedState)).toThrow(/final state mismatch/);
  });

  it("throws when a replay input is recorded at the wrong tick", () => {
    const trace = clone(captured());
    trace.replay.inputs[4]!.tick = 19;
    expect(() => replayArenaTrace(trace)).toThrow(/input 4 \(step\) was recorded at tick 19/);
  });

  it("throws when any part of the recorded terminal record disagrees", () => {
    for (const [field, value] of [["status", "abandoned"], ["tick", 23], ["reason", "player_quit"]] as const) {
      const trace = clone(captured());
      (trace.terminal as Record<string, unknown>)[field] = value;
      expect(validateArenaTraceV3(trace).valid).toBe(true);
      expect(() => replayArenaTrace(trace)).toThrow(/terminal mismatch/);
    }
  });

  it("applies a single recorded input and checks where it landed", () => {
    const trace = captured();
    const game = new RestaurantGame(trace.seed, trace.replay.variation);

    applyArenaReplayInput(game, trace.replay.inputs[0]!, 0);
    expect(computeStateHash(game.checkpointState())).toBe(trace.replay.inputs[0]!.stateHash);
    // Out of order is a divergence, not something to paper over.
    expect(() => applyArenaReplayInput(game, trace.replay.inputs[9]!, 9)).toThrow(/tick/);
  });
});

import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { roundForTick } from "./rounds.js";
import {
  ARENA_ENV_VERSION,
  TRACE_V3_CONTRACT_VERSION,
  TRACE_V3_VERSION,
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

/** A short shift that reaches the correction, the probe and the outcome. */
function playedShift(seed = 218220): RestaurantGame {
  const game = new RestaurantGame(seed, "dinner-rush");
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  while (!game.isOver()) game.step("tick");
  return game;
}

function capturedShift(): RestaurantArenaTraceV3 {
  return playedShift().captureTrace({ runKind: "benchmark" });
}

describe("Restaurant Arena trace capture (v3)", () => {
  it("captures the whole record from a running game", () => {
    const game = playedShift();
    const trace = game.captureTrace({ runKind: "live" });

    expect(trace.version).toBe(TRACE_V3_VERSION);
    expect(trace.contractVersion).toBe(TRACE_V3_CONTRACT_VERSION);
    expect(trace.envVersion).toBe(ARENA_ENV_VERSION);
    expect(trace.runKind).toBe("live");
    expect(trace.seed).toBe(218220);
    expect(trace.episodeId).toBe(game.state().episode.id);
    expect(trace.sessionId).toBeUndefined();
    expect(trace.initialState).toEqual(game.getInitialState());
    expect((trace.initialState as { episode: { tick: number } }).episode.tick).toBe(0);
    expect(trace.events).toEqual(game.getRecordedEvents());
    expect(trace.replay).toEqual(game.getReplayRecord());
    expect(trace.deletion).toEqual({ requestId: null, status: "retained" });
    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
  });

  it("records the terminal object the engine reports, not just its status", () => {
    const trace = capturedShift();
    expect(trace.terminal).toEqual({ status: "completed", tick: 24, reason: "episode_complete" });
  });

  it("captures the same record through the instance method and the standalone helper", () => {
    const game = playedShift();
    expect(game.captureTrace({ runKind: "synthetic", episodeId: "probe-run" }))
      .toEqual(captureArenaTrace(game, { runKind: "synthetic", episodeId: "probe-run" }));
  });

  it("requires a runKind so live, synthetic and benchmark runs stay distinguishable", () => {
    const game = playedShift();
    expect(() => game.captureTrace({} as { runKind: "live" })).toThrow(/runKind/);
    expect(() => game.captureTrace({ runKind: "practice" as "live" })).toThrow(/runKind/);
    for (const runKind of ["live", "synthetic", "benchmark"] as const) {
      expect(game.captureTrace({ runKind }).runKind).toBe(runKind);
    }
  });

  it("identifies the session a trace came from when the caller knows it (#281)", () => {
    const game = playedShift();
    const first = game.captureTrace({ runKind: "live", sessionId: "session-one" });
    const second = game.captureTrace({ runKind: "live", sessionId: "session-two" });

    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).not.toBe(second.sessionId);
    expect(validateArenaTraceV3(first).valid).toBe(true);
  });

  it("stamps caller-supplied extra events with the round their tick falls in", () => {
    const game = playedShift();
    const note: TraceV3Event = {
      tick: 13,
      kind: "message",
      timestamp: "2026-09-05T18:00:39.000Z",
      stateHash: `sha256:${"0".repeat(64)}`,
      actorId: "player",
      text: "Out-of-band note from the pass.",
    };
    const opening: TraceV3Event = { ...note, tick: 0, text: "Pre-service briefing." };
    const trace = game.captureTrace({ runKind: "live", additionalEvents: [note, opening] });

    const added = trace.events.filter((event) => event.actorId === "player" && event.text?.includes("note") === true);
    expect(added).toHaveLength(1);
    expect(added[0]!.round).toBe(roundForTick(13));
    expect(added[0]!.round).toBe(7);
    expect(trace.events.find((event) => event.text === "Pre-service briefing.")!.round).toBe(1);
    // Merged into the journal in tick order, and the journal itself is intact.
    expect(trace.events).toHaveLength(game.getRecordedEvents().length + 2);
    expect(trace.events.map((event) => event.tick)).toEqual([...trace.events.map((event) => event.tick)].sort((a, b) => a - b));
    expect(validateArenaTraceV3(trace)).toEqual({ valid: true, errors: [] });
  });

  it("replaces the journal wholesale when events are supplied", () => {
    const game = playedShift();
    const only: TraceV3Event[] = [{
      tick: 2,
      kind: "outcome",
      timestamp: "2026-09-05T18:00:06.000Z",
      stateHash: `sha256:${"a".repeat(64)}`,
      round: 1,
    }];
    expect(game.captureTrace({ runKind: "synthetic", events: only }).events).toEqual(only);
  });

  it("derives event timestamps from a given start time so an export is reproducible", () => {
    const trace = playedShift().captureTrace({ runKind: "benchmark", startTime: "2026-09-05T18:00:00.000Z" });
    expect(trace.events[0]!.timestamp).toBe("2026-09-05T18:00:00.000Z");
    expect(trace.events.at(-1)!.timestamp).toBe("2026-09-05T18:01:12.000Z");
    expect(() => playedShift().captureTrace({ runKind: "benchmark", startTime: "not-a-date" })).toThrow(/startTime/);
  });

  it("carries the deletion record, defaulting to retained", () => {
    const game = playedShift();
    expect(game.captureTrace({ runKind: "live" }).deletion).toEqual({ requestId: null, status: "retained" });
    expect(game.captureTrace({ runKind: "live", deletion: { status: "requested", requestId: "del-1" } }).deletion)
      .toEqual({ requestId: "del-1", status: "requested" });
    expect(game.captureTrace({ runKind: "live", deletion: { status: "deleted" } }).deletion)
      .toEqual({ requestId: null, status: "deleted" });
  });
});

describe("Restaurant Arena trace export (v3)", () => {
  it("exports an indented JSON document that parses back to the same record", () => {
    const trace = capturedShift();
    const json = exportTraceJson(trace);

    expect(JSON.parse(json)).toEqual(JSON.parse(JSON.stringify(trace)));
    expect(json.startsWith("{\n  \"version\": \"restaurant-arena-trace/v3\"")).toBe(true);
    expect(json.endsWith("\n")).toBe(false);
    // Float fields keep their decimal spelling so the backend reads the same numbers.
    expect(json).toContain("\"reputation\": 50.0");
    expect(validateArenaTraceV3(JSON.parse(json))).toEqual({ valid: true, errors: [] });
  });

  it("exports JSONL as one header line plus one line per event", () => {
    const trace = capturedShift();
    const lines = exportTraceJsonl(trace).split("\n");

    expect(lines).toHaveLength(trace.events.length + 1);
    const header = JSON.parse(lines[0]!);
    expect(header.events).toBeUndefined();
    expect(header).toMatchObject({ version: trace.version, replay: trace.replay, terminal: trace.terminal });
    expect(lines.slice(1).map((line) => JSON.parse(line))).toEqual(JSON.parse(JSON.stringify(trace.events)));
    // Re-assembling the stream gives the record back.
    expect(validateArenaTraceV3({ ...header, events: lines.slice(1).map((line) => JSON.parse(line)) }).valid).toBe(true);
  });
});

describe("Restaurant Arena trace validation (v3)", () => {
  const tampered = (mutate: (trace: Record<string, any>) => void): string[] => {
    const trace = JSON.parse(JSON.stringify(capturedShift()));
    mutate(trace);
    const result = validateArenaTraceV3(trace);
    expect(result.valid).toBe(false);
    return result.errors;
  };

  it("accepts the record the engine itself captures", () => {
    expect(validateArenaTraceV3(capturedShift())).toEqual({ valid: true, errors: [] });
  });

  it("rejects a value that is not a record at all", () => {
    for (const value of [null, 7, "trace", []]) {
      expect(validateArenaTraceV3(value).valid).toBe(false);
    }
  });

  it("names every missing required field", () => {
    const errors = tampered((trace) => {
      delete trace.seed;
      delete trace.deletion;
      delete trace.terminal;
    });
    expect(errors).toContain("seed: is required");
    expect(errors).toContain("deletion: is required");
    expect(errors).toContain("terminal: is required");
  });

  it("rejects the wrong version or contract version", () => {
    expect(tampered((trace) => { trace.version = "restaurant-arena-trace/v2"; }))
      .toContain("version: must be \"restaurant-arena-trace/v3\"");
    expect(tampered((trace) => { trace.contractVersion = "restaurant-arena/v2"; }))
      .toContain("contractVersion: must be \"restaurant-arena/v1\"");
  });

  it("rejects field by field: ids, run kinds, seeds and env versions", () => {
    expect(tampered((trace) => { trace.runKind = "practice"; })[0]).toContain("runKind");
    expect(tampered((trace) => { trace.seed = -1; })).toContain("seed: must be at least 0");
    expect(tampered((trace) => { trace.seed = 1.5; })).toContain("seed: must be an integer");
    expect(tampered((trace) => { trace.envVersion = ""; })[0]).toContain("envVersion");
    expect(tampered((trace) => { trace.episodeId = "not a valid id"; })[0]).toContain("episodeId");
    expect(tampered((trace) => { trace.sessionId = "-leading-dash"; })[0]).toContain("sessionId");
    expect(tampered((trace) => { trace.unexpected = true; }))
      .toContain("unexpected: is not a field of this record");
  });

  it("rejects a malformed initial state", () => {
    expect(tampered((trace) => { delete trace.initialState.workers; }))
      .toContain("initialState.workers: is required");
    expect(tampered((trace) => { trace.initialState.workers[0].role = "expo"; })[0])
      .toContain("initialState.workers[0].role");
    expect(tampered((trace) => { trace.initialState.workers[0].load = 4; }))
      .toContain("initialState.workers[0].load: must be at most 1");
    expect(tampered((trace) => { trace.initialState.episode.phase = "paused"; })[0])
      .toContain("initialState.episode.phase");
    expect(tampered((trace) => { trace.initialState.inventory.pasta = -2; }))
      .toContain("initialState.inventory.pasta: must be at least 0");
    expect(tampered((trace) => { trace.initialState.reputation = 140; }))
      .toContain("initialState.reputation: must be at most 100");
  });

  it("rejects malformed events", () => {
    expect(tampered((trace) => { delete trace.events[0].stateHash; }))
      .toContain("events[0].stateHash: is required");
    expect(tampered((trace) => { trace.events[0].stateHash = "sha256:nope"; })[0])
      .toContain("events[0].stateHash");
    expect(tampered((trace) => { trace.events[0].kind = "chatter"; })[0]).toContain("events[0].kind");
    expect(tampered((trace) => { trace.events[0].tick = -1; }))
      .toContain("events[0].tick: must be at least 0");
    expect(tampered((trace) => { trace.events[0].timestamp = "yesterday"; })[0])
      .toContain("events[0].timestamp");
    expect(tampered((trace) => { trace.events[0].round = 0; }))
      .toContain("events[0].round: must be at least 1");
    expect(tampered((trace) => { trace.events[0].role = "expo"; })[0]).toContain("events[0].role");
    expect(tampered((trace) => { trace.events[0].idempotencyKey = "no spaces allowed"; })[0])
      .toContain("events[0].idempotencyKey");
    expect(tampered((trace) => { trace.events[0].model = { provider: "anthropic" }; }))
      .toContain("events[0].model.name: is required");
    expect(tampered((trace) => { trace.events[0].subject = { kind: "order" }; }))
      .toContain("events[0].subject.id: is required");
    expect(tampered((trace) => { trace.events[0].smuggled = 1; }))
      .toContain("events[0].smuggled: is not a field of this record");
  });

  it("keeps a tool result's failure keys consistent", () => {
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: false }; }))
      .toContain("events[0].toolResult.error: is required when ok is false");
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: true, error: { code: "x", message: "y" } }; }))
      .toContain("events[0].toolResult.ok: must be false when an error is present");
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: false, error: { code: "x" } }; }))
      .toContain("events[0].toolResult.error.message: is required");
    expect(tampered((trace) => { trace.events[0].toolResult = { ok: true, latencyMs: -3 }; }))
      .toContain("events[0].toolResult.latencyMs: must be at least 0");
    // Domain keys ride alongside the reserved ones untouched.
    const fine = JSON.parse(JSON.stringify(capturedShift()));
    fine.events[0].toolResult = { ok: true, status: "verified", latencyMs: 12, checked: 3 };
    expect(validateArenaTraceV3(fine).valid).toBe(true);
  });

  it("rejects malformed replay inputs", () => {
    expect(tampered((trace) => { trace.replay.variation = "monday-lunch"; })[0])
      .toContain("replay.variation");
    expect(tampered((trace) => { trace.replay.finalStateHash = "sha256:XYZ"; })[0])
      .toContain("replay.finalStateHash");
    expect(tampered((trace) => { delete trace.replay.inputs[0].action; }))
      .toContain("replay.inputs[0].action: is required");
    expect(tampered((trace) => { trace.replay.inputs[0].kind = "teleport"; })[0])
      .toContain("replay.inputs[0].kind");
    expect(tampered((trace) => { trace.replay.inputs[0].stateHash = "deadbeef"; })[0])
      .toContain("replay.inputs[0].stateHash");
    expect(tampered((trace) => { trace.replay.inputs[0].note = "hand written"; }))
      .toContain("replay.inputs[0].note: is not a field of this record");
    expect(tampered((trace) => { trace.replay.inputs[0] = { kind: "controllers", tick: 0, stateHash: trace.replay.inputs[0].stateHash, roles: ["chef", "chef"] }; }))
      .toContain("replay.inputs[0].roles: must not repeat an entry");
    expect(tampered((trace) => {
      trace.replay.inputs[0] = {
        kind: "envelope",
        tick: 0,
        stateHash: trace.replay.inputs[0].stateHash,
        envelope: { version: "restaurant-arena-action/v1", episodeId: "dinner-rush-001", actorId: "player", actorType: "player", role: "chef", tool: "levitate", arguments: {}, tick: 0, timestamp: "2026-09-05T18:00:00.000Z", requestId: "r1", idempotencyKey: "dinner-rush-001:r1" },
      };
    })[0]).toContain("replay.inputs[0].envelope.tool");
  });

  it("rejects a malformed terminal or deletion record", () => {
    expect(tampered((trace) => { delete trace.terminal.reason; })).toContain("terminal.reason: is required");
    expect(tampered((trace) => { trace.terminal.status = "finished"; })[0]).toContain("terminal.status");
    expect(tampered((trace) => { trace.terminal.tick = "24"; })).toContain("terminal.tick: must be an integer");
    expect(tampered((trace) => { trace.deletion.status = "shredded"; })[0]).toContain("deletion.status");
    expect(tampered((trace) => { delete trace.deletion.requestId; })).toContain("deletion.requestId: is required");
    // A retained record's requestId is legitimately null.
    const fine = JSON.parse(JSON.stringify(capturedShift()));
    fine.terminal.reason = null;
    fine.deletion.requestId = null;
    expect(validateArenaTraceV3(fine).valid).toBe(true);
  });
});

/**
 * Natively replay a trace file and report whether the record is true.
 *
 *   bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>
 *
 * Accepts both export shapes: the indented JSON document from
 * `exportTraceJson` and the header-plus-events stream from `exportTraceJsonl`.
 * The trace has to pass schema validation *and* replay — every checkpoint hash,
 * the final hashes, and the whole terminal record — before this prints a pass.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { validateArenaTraceV3, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(2);
}

/** JSONL is one header line then one line per event; JSON is the whole record. */
function parseTrace(path: string, raw: string): RestaurantArenaTraceV3 {
  if (!path.endsWith(".jsonl")) return JSON.parse(raw) as RestaurantArenaTraceV3;
  const lines = raw.split("\n").filter((line) => line.trim().length > 0);
  const [header, ...events] = lines;
  if (!header) throw new Error("trace file is empty");
  return {
    ...(JSON.parse(header) as RestaurantArenaTraceV3),
    events: events.map((line) => JSON.parse(line)),
  };
}

const [target, ...rest] = process.argv.slice(2);
if (!target || rest.length > 0) usage();
const path = resolve(target);

try {
  const trace = parseTrace(path, readFileSync(path, "utf8"));
  const validation = validateArenaTraceV3(trace);
  if (!validation.valid) {
    console.error(`Schema validation failed for ${target}:\n${validation.errors.join("\n")}`);
    process.exit(1);
  }
  const game = replayArenaTrace(trace);
  const terminal = game.getTerminalStatus();
  console.log(
    `Native replay passed: ${trace.replay.inputs.length} inputs, tick ${terminal.tick}, ${terminal.status} (${terminal.reason ?? "no reason"})`,
  );
  console.log(`Final checkpoint ${trace.replay.finalStateHash}`);
} catch (error) {
  console.error(`Native replay failed for ${target}: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}
